window.MOTIF_CATALOG_CHUNKS[50]={"cards":[{"id":"MEJE-KW-005101","row_version":1,"title":"학급 대표","original":"Class Representative","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"반의 일을 맡아 학생과 교사 사이에서 의견을 전하는 학생. 책임감이 친구들의 일탈과 부딪치며 갈등이 되기도 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005101/index.html"},{"id":"MEJE-KW-005102","row_version":1,"title":"동창회","original":"Class Reunion","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"예전 급우들이 다시 모여 학창 시절의 관계와 현재의 모습을 비교한다. 한때의 서열이 뒤집히거나 남아 있는 모습이 드러난다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005102/index.html"},{"id":"MEJE-KW-005104","row_version":1,"title":"학급 단체여행","original":"Class Trip","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"학생들이 교실을 떠나 함께 방문한 곳에서 새로운 사건을 겪는다. 낯선 장소가 평소의 친구 관계를 다른 각도에서 드러낸다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-005104/index.html"},{"id":"MEJE-KW-005105","row_version":2,"title":"품위를 나타내는 지팡이","original":"Classy Cane","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 기능적인 필요 외에도 격식과 지위를 보여 주는 지팡이를 든다. 작은 소품이 걸음걸이와 계층 이미지를 함께 만든다. 지팡이와 함께 격식을 드러내는 크라바트를 더하면 복식으로 격식과 계층을 강조할 수 있다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005105/index.html"},{"id":"MEJE-KW-005106","row_version":1,"title":"우아한 괴도","original":"Classy Cat-Burglar","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"도둑이 세련된 태도와 매력으로 범죄를 낭만적인 모험처럼 보이게 한다. 매력에 흔들리는 주변 인물과 실제 피해 사이의 거리가 긴장을 만든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005106/index.html"},{"id":"MEJE-KW-005107","row_version":1,"title":"격식을 드러내는 크라바트","original":"Classy Cravat","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"목에 묶는 장식 천으로 인물의 부와 옛 취향, 격식을 표현한다. 복식의 작은 부분이 시대와 계층의 단서를 준다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-005107/index.html"},{"id":"MEJE-KW-005108","row_version":1,"title":"밀폐 공간 공포","original":"Claustrophobia","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 좁고 닫힌 장소에서 벗어나지 못할 것 같은 두려움을 느낀다. 공간의 압박이 판단과 관계에 영향을 미치는 서사적 상태다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-005108/index.html"},{"id":"MEJE-KW-005109","row_version":1,"title":"목을 긁는 불안 행동","original":"Clawing at Own Throat","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 극심한 불안이나 혼란 속에서 스스로 목 주변을 긁는 모습을 보인다. 신체 동작 하나로 위태로운 심리 상태를 암시한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005109/index.html"},{"id":"MEJE-KW-005110","row_version":1,"title":"흔적 없이 지나가는 칼날","original":"Clean Cut","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품 속 날붙이가 믿기 어려울 만큼 매끈하게 대상을 가른다. 상처의 복잡함을 생략하고 무기의 날카로움이나 전투의 속도를 강조하는 연출이다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005110/index.html"},{"id":"MEJE-KW-005111","row_version":1,"title":"단정하지만 순진한 모르몬교인이라는 인물형","original":"Clean-Cut Naïve Mormon","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"모르몬교 신자를 단정한 차림과 엄격한 생활 규범을 지닌 순진한 인물로 묘사한다. 실제 신앙인을 한 가지 성격으로 묶는 고정관념이 될 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005111/index.html"},{"id":"MEJE-KW-005112","row_version":1,"title":"더빙에서 불편한 이름만 살짝 바꾸기","original":"Clean Dub Name","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"다른 언어에서 민망하거나 공격적으로 들리는 이름을 더빙 과정에서 조금 고친다. 원래 이름의 알아볼 만한 형태를 남기면서 현지 언어의 인상을 조정한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005112/index.html"},{"id":"MEJE-KW-005113","row_version":1,"title":"음식은 멀쩡하지만 식기가 위험한 만찬","original":"Clean Food, Poisoned Fork","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"식사 장면에서 음식 자체는 안전해 보이지만 곁의 식기나 잔에 위험이 숨어 있다. 인물의 주의가 향한 대상과 실제 위협의 위치가 어긋나 반전을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005113/index.html"},{"id":"MEJE-KW-005114","row_version":1,"title":"결말에서 남은 구애 관계 정리하기","original":"Cleaning Up Romantic Loose Ends","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"주인공이 한 사람을 선택한 뒤 다른 구애자들에게도 새 관계나 갈 길을 마련한다. 남겨진 인물의 감정선을 마무리하며 결말의 후유증을 줄인다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005114/index.html"},{"id":"MEJE-KW-005115","row_version":1,"title":"지나치게 깔끔한 출산 장면","original":"Clean, Pretty Childbirth","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"출산의 시간과 몸의 변화를 거의 보이지 않은 채 깨끗한 아기와 단정한 산모만 보여 준다. 복잡한 신체 경험을 빠른 장면 전환과 매끈한 이미지로 단순화한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005115/index.html"},{"id":"MEJE-KW-005116","row_version":1,"title":"사건의 흔적을 지우는 뒷정리 조직","original":"Cleanup Crew","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"범죄나 비밀 활동의 현장에 전문 인력이 나타나 사건의 흔적을 지운다. 이들의 존재는 배후 조직의 자원과 은폐 능력을 보여 준다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-005116/index.html"},{"id":"MEJE-KW-005117","row_version":1,"title":"무법천지를 바로잡으러 온 인물","original":"Clean Up the Town","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"새로 오거나 돌아온 인물이 부패한 마을의 질서를 바꾸려 한다. 개인의 행동이 오래된 권력 구조와 충돌하면서 공동체의 변화를 이끈다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005117/index.html"},{"id":"MEJE-KW-005118","row_version":2,"title":"누명을 벗으려는 당사자","original":"Clear My Name","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"억울하게 범인으로 몰린 인물이 스스로 결백의 증거를 찾는다. 사건 해결과 자기 삶을 되찾는 목표가 하나로 묶인다. 당사자가 직접 움직일 수 없을 때는 다른 사람이 진실을 밝히는 역할을 맡는다: 타인의 누명을 벗겨 주기.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005118/index.html"},{"id":"MEJE-KW-005119","row_version":2,"title":"타인의 누명을 벗겨 주기","original":"Clear Their Name","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"억울하게 몰린 사람 대신 다른 인물이 증거를 모아 진실을 밝히려 한다. 당사자를 믿는 관계가 수사의 출발점이 된다. 누명을 쓴 사람이 스스로 증거를 찾아 나서는 전개와 주도권이 다르다: 누명을 벗으려는 당사자.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005119/index.html"},{"id":"MEJE-KW-005120","row_version":1,"title":"가슴 부분이 트인 의상","original":"Cleavage Window","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"옷의 가슴 부위에 둘러싸인 틈을 내 피부가 보이도록 디자인한다. 의상에서 시선이 집중되는 위치와 인물의 이미지가 함께 정해진다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005120/index.html"},{"id":"MEJE-KW-005121","row_version":1,"title":"클리블랜드를 깎아내리는 도시 농담","original":"Cleveland Sucks","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"미국의 특정 도시를 칙칙하거나 뒤처진 곳으로 조롱하는 농담을 반복한다. 실제 도시의 다양성을 지우고 지역에 붙은 평판을 웃음의 재료로 삼는다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005121/index.html"},{"id":"MEJE-KW-005122","row_version":1,"title":"영리한 까마귀","original":"Clever Crows","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"까마귀나 큰까마귀를 문제를 풀고 상황을 읽는 영리한 동물로 그린다. 검은 깃털의 불길한 이미지와 뛰어난 지능이 한 존재 안에 겹친다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-005122/index.html"},{"id":"MEJE-KW-005123","row_version":2,"title":"악역에게 식상하다고 비웃기","original":"\"Clichéd Villain\" Accusation","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"주인공이 악역의 계획이나 말투가 뻔한 이야기에서 나온 것 같다고 지적한다. 메타적인 조롱으로 상대의 위세를 낮춘다. 악역 한 사람의 뻔한 행동을 비웃는 데서 더 나아가 작품 전체가 익숙한 장치로 가득할 수도 있다: 클리셰가 한꺼번에 몰려오는 이야기.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005123/index.html"},{"id":"MEJE-KW-005124","row_version":1,"title":"클리셰가 한꺼번에 몰려오는 이야기","original":"Cliché Storm","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"익숙한 대사와 장면, 인물형이 짧은 구간에 연달아 나타난다. 개별 요소보다 반복의 밀도가 작품의 인상을 결정한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-005124/index.html"},{"id":"MEJE-KW-005125","row_version":1,"title":"낚시성 제목과 썸네일을 희화화하기","original":"Clickbait Gag","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"관심을 끌려고 과장한 제목과 이미지를 작품 안에서 노골적으로 흉내 낸다. 클릭을 유도하는 온라인 관습 자체가 웃음의 대상이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005125/index.html"},{"id":"MEJE-KW-005126","row_version":1,"title":"딸깍 소리로 알리는 등 뒤의 위협","original":"*Click* Hello","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"한 인물이 무언가에 몰두한 사이 뒤쪽에서 짧은 기계음이 들려 위협의 존재를 알린다. 먼저 들린 소리가 보이지 않는 상대를 상상하게 만든다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-005126/index.html"},{"id":"MEJE-KW-005127","row_version":3,"title":"위기 한복판에서 끝내기","original":"Cliffhanger","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"회차나 권의 끝을 인물의 위험이나 중대한 미해결 상황에서 끊는다. 다음 이야기가 나올 때까지 기다리는 시간이 긴장에 더해진다. 오랫동안 붙든 위기가 다음 회차에서 너무 쉽게 풀리면 기대와 해소 사이에 간극이 생긴다: 다음 편에서 쉽게 무너지는 절박한 결말. 다음 이야기가 위기의 해답 대신 다른 시점으로 돌아서면 미해결 상태가 더 길어진다: 풀리지 않은 절정 뒤로 돌아서는 연재.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005127/index.html"},{"id":"MEJE-KW-005128","row_version":2,"title":"다음 편에서 쉽게 무너지는 절박한 결말","original":"Cliffhanger Copout","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"앞선 회차가 큰 위기처럼 보였지만 다음 회차에서 뜻밖에 간단한 해답이 제시된다. 기다려 온 관객의 기대와 실제 해소의 무게가 어긋난다. 쉽게 풀리는 위기는 앞선 회차가 위험한 순간에서 멈췄기에 가능했던 기대를 비튼다: 위기 한복판에서 끝내기.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005128/index.html"},{"id":"MEJE-KW-005129","row_version":1,"title":"풀리지 않은 절정 뒤로 돌아서는 연재","original":"Cliffhanger Wall","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 큰 전환점에서 멈춘 뒤 다음 이야기가 그 사건을 이어가지 않고 외전이나 과거 이야기로 돌아선다. 핵심 질문이 오래 미뤄지며 연재의 흐름이 달라진다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005129/index.html"},{"id":"MEJE-KW-005130","row_version":1,"title":"벼랑 앞에 멈춘 무리를 밀어 버리는 마지막 사람","original":"Cliff Stack","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"집단이 추락 직전 가까스로 멈췄다가 뒤늦게 달려온 사람이 부딪쳐 함께 넘어간다. 한 박자 늦은 충돌이 몸개그의 결말을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005130/index.html"},{"id":"MEJE-KW-005131","row_version":1,"title":"높은 곳에서 감정을 토해 내기","original":"Clifftop Caterwauling","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이나 동물이 절벽 끝이나 높은 지붕에 서서 울부짖거나 포효한다. 높은 위치와 열린 하늘이 승리나 슬픔의 크기를 시각화한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005131/index.html"},{"id":"MEJE-KW-005132","row_version":2,"title":"최종전에서 쓰러진 동료 되살리기","original":"Climactic Battle Resurrection","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"결전 끝에 살아남은 인물이 쓰러진 동료들을 돌아오게 한다. 치열했던 전투의 상실을 회복으로 바꾸며 승리의 의미를 정리한다. 결전에서 모두 돌아오더라도 어떤 인물에게는 지워지지 않는 상처가 남을 수 있다: 결전에서 남는 신체의 상처.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005132/index.html"},{"id":"MEJE-KW-005133","row_version":2,"title":"결전을 앞둔 긴 엘리베이터 탑승","original":"Climactic Elevator Ride","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물들이 최종 대결 장소로 올라가는 엘리베이터 안에서 무기와 마음을 가다듬는다. 좁은 공간의 정적이 곧 열릴 문 너머의 충돌을 키운다. 엘리베이터로 곧장 올라가는 대신 추격 끝에 높은 곳으로 몰리는 결전도 있다: 끝을 앞두고 높은 곳으로 도망치는 악역.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005133/index.html"},{"id":"MEJE-KW-005134","row_version":1,"title":"결전에서 남는 신체의 상처","original":"Climactic Maiming","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"최종 대결에서 인물이 목숨을 건지더라도 몸의 일부나 능력을 잃는다. 승리 뒤에도 남는 상처가 싸움의 대가를 보이게 한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005134/index.html"},{"id":"MEJE-KW-005135","row_version":1,"title":"절정과 함께 치솟는 음악","original":"Climactic Music","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"이야기의 가장 중요한 순간에 음악의 크기와 구성도 정점에 이른다. 소리의 상승이 장면의 긴장이나 성취감을 함께 끌어올린다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-005135/index.html"},{"id":"MEJE-KW-005136","row_version":1,"title":"화산을 등진 최종 대결","original":"Climactic Volcano Backdrop","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"결전의 무대를 화산과 용암이 보이는 곳에 놓는다. 불안정한 지형과 강한 색채가 인물 사이의 극단적 감정을 확대한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005136/index.html"},{"id":"MEJE-KW-005137","row_version":1,"title":"기후변화를 비추는 재난 우화","original":"Climate Change Allegory","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"인간의 행동이 불러온 광범위한 환경 변화를 다른 재난이나 초자연적 사건으로 바꾸어 그린다. 현실의 기후 문제를 세계관의 위기로 다시 생각하게 한다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-005137/index.html"},{"id":"MEJE-KW-005138","row_version":1,"title":"이야기의 전환점에 놓인 보스전","original":"Climax Boss","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임의 중요한 폭로나 국면 전환 가까이에 큰 전투를 배치한다. 승패가 단순한 난관 통과를 넘어 이야기의 방향을 바꾼다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005138/index.html"},{"id":"MEJE-KW-005139","row_version":2,"title":"끝을 앞두고 높은 곳으로 도망치는 악역","original":"Climbing Climax","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"쫓기던 악역이 높은 건물이나 탑을 올라가며 추격전을 결전으로 몰아간다. 올라갈수록 도망칠 길이 줄고 시각적 위험은 커진다. 높이 자체를 관문으로 만드는 장면은 추격전 밖의 여정에도 나타난다: 험한 절벽을 넘어야 하는 여정.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005139/index.html"},{"id":"MEJE-KW-005140","row_version":2,"title":"오르기를 직접 다루는 게임 규칙","original":"Climbing Mechanics","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어가 벽과 사물에 매달리거나 올라가며 이동한다. 수직 공간이 새로운 길과 실패 가능성을 만드는 탐색 규칙이 된다. 게임의 오르기 규칙은 이야기 속 가파른 절벽을 직접 넘는 경험으로 바꿀 수 있다: 험한 절벽을 넘어야 하는 여정.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005140/index.html"},{"id":"MEJE-KW-005141","row_version":2,"title":"험한 절벽을 넘어야 하는 여정","original":"Climbing the Cliffs of Insanity","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"목적지로 가는 길목에 가파른 벽이나 절벽이 나타나 일행의 전진을 막는다. 높이와 추락 위험이 이동 자체를 시험으로 바꾼다. 절벽을 넘는 도중 한 번 미끄러지는 사건이 추락 위험을 더 구체적으로 보여 준다: 오르다 미끄러졌다 다시 붙잡기.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005141/index.html"},{"id":"MEJE-KW-005142","row_version":1,"title":"오르다 미끄러졌다 다시 붙잡기","original":"Climb, Slip, Hang, Climb","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"절벽을 오르는 인물이 발을 헛디뎌 잠시 매달린 뒤 다시 몸을 끌어올린다. 한 번의 흔들림이 추락 가능성을 관객에게 체감시킨다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005142/index.html"},{"id":"MEJE-KW-005143","row_version":1,"title":"물에서 나오니 몸에 붙은 생물들","original":"Clingy Aquatic Life","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 물 밖으로 올라왔을 때 해초나 작은 수생 생물이 몸에 달라붙어 있다. 젖은 몸의 불편함을 눈에 띄는 소동으로 바꾼다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005143/index.html"},{"id":"MEJE-KW-005144","row_version":1,"title":"보호자에게 꼭 붙어 있는 아이","original":"Clingy Child","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"아이가 보호자의 손이나 다리를 놓지 않으려 한다. 애정과 불안, 낯선 장소에 대한 두려움이 행동에 드러난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005144/index.html"},{"id":"MEJE-KW-005145","row_version":2,"title":"벗을 수 없는 의상","original":"Clingy Costume","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 의상을 벗으려 해도 몸이나 특별한 규칙 때문에 계속 입어야 한다. 옷이 장식에서 생존과 정체성을 좌우하는 조건으로 바뀐다. 몸에 붙은 옷처럼 소유자와 떨어지지 않는 물건도 별도의 이야기를 만든다: 버려도 돌아오는 중요한 물건.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005145/index.html"},{"id":"MEJE-KW-005146","row_version":1,"title":"질투로 매달리는 연인","original":"Clingy Jealous Girl","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"연인이 상대에게 끊임없이 붙어 있으려 하고 작은 관심 이동에도 질투한다. 친밀함을 원하는 마음이 상대의 자유를 좁히는 갈등으로 커진다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005146/index.html"},{"id":"MEJE-KW-005147","row_version":1,"title":"버려도 돌아오는 중요한 물건","original":"Clingy MacGuffin","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물이 없애거나 넘기려는 물건이 어떤 이유로든 계속 곁에 남는다. 소유 관계를 끊을 수 없다는 규칙이 사건을 이어 간다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005147/index.html"},{"id":"MEJE-KW-005148","row_version":1,"title":"잠결에 서로를 붙잡고 자는 두 사람","original":"Clingy Sleepers","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"함께 밤을 보낸 두 인물이 아침에 서로를 꼭 끌어안은 채 잠들어 있었음을 알게 된다. 의식하지 못한 친밀함이 깨어난 뒤의 어색함을 만든다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005148/index.html"},{"id":"MEJE-KW-005149","row_version":1,"title":"눈을 가늘게 뜨는 강인한 표정","original":"Clint Squint","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 눈을 좁게 뜨고 상대나 먼 곳을 바라보며 냉정한 인상을 준다. 표정 하나로 경계와 위압감을 강조한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005149/index.html"},{"id":"MEJE-KW-005150","row_version":1,"title":"기성 그림을 움직이는 애니메이션","original":"Clip-Art Animation","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"이미 있는 그림을 화면에서 옮기거나 돌리는 방식으로 움직임을 만든다. 제한된 제작 조건을 드러내기도 하고 일부러 거친 맛을 내기도 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005150/index.html"},{"id":"MEJE-KW-005151","row_version":1,"title":"클립보드로 빌린 권위","original":"Clipboard of Authority","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"서류판을 든 인물이 업무 담당자처럼 보여 주변의 의심을 덜 받는다. 평범한 사무용품이 제도적 권위를 상징하는 소품으로 쓰인다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005151/index.html"},{"id":"MEJE-KW-005152","row_version":1,"title":"날개를 잃어 나는 힘을 잃기","original":"Clip Its Wings","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"날 수 있는 존재가 날개를 다쳐 공중에서 내려오거나 더는 날지 못한다. 가장 큰 능력을 잃는 순간이 취약함을 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005152/index.html"},{"id":"MEJE-KW-005153","row_version":1,"title":"기대에 못 미친 최종 변신","original":"Clipped-Wing Angel","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"악역이 압도적인 새 모습으로 변하지만 실제 힘이나 효용은 기대보다 못하다. 위협적인 외형과 초라한 결과의 차이가 반전을 만든다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005153/index.html"},{"id":"MEJE-KW-005154","row_version":1,"title":"이전 장면을 다시 모아 보여 주는 회차","original":"Clip Show","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"연재 작품의 한 회차를 과거 장면의 재구성과 짧은 새 이야기로 채운다. 기억을 정리하거나 제작 여건을 맞추는 형식이 된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005154/index.html"},{"id":"MEJE-KW-005155","row_version":1,"title":"새로 온 사람을 위한 파벌 안내","original":"Clique Tour","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"익숙한 사람이 새로 온 인물에게 공간의 여러 무리와 각자의 특징을 소개한다. 짧은 안내가 관계망과 사회적 경계를 드러낸다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005155/index.html"},{"id":"MEJE-KW-005156","row_version":1,"title":"큰 사건에서 소모되는 비주류 인물","original":"C-List Fodder","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품이 큰 변화를 예고하면서도 중심 인물 대신 덜 알려진 인물에게 희생을 집중한다. 변화의 규모와 실제 손실의 차이가 드러난다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005156/index.html"},{"id":"MEJE-KW-005157","row_version":2,"title":"공식 조직 밖의 비밀 첩보 집단","original":"Cloak and Dagger","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"국가 기관과 분리된 비밀 집단이 첩보와 은밀한 작전을 맡는다. 명확한 감독선이 없어 행동의 책임과 목적이 흐려지기 쉽다. 비밀 조직이 활동의 흔적을 감추기 위해 전문 인력을 둘 수도 있다: 사건의 흔적을 지우는 뒷정리 조직.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-005157/index.html"},{"id":"MEJE-KW-005158","row_version":1,"title":"공격을 막아 주는 망토","original":"Cloak of Defense","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"망토나 외투가 외형 장식에 그치지 않고 인물을 보호하는 장비가 된다. 몸을 감싸는 천의 이미지가 실제 방어 능력으로 이어진다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005158/index.html"},{"id":"MEJE-KW-005159","row_version":1,"title":"덮개를 열어 드러내는 뜻밖의 물건","original":"Cloche Surprise","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"접시 위의 돔형 덮개를 들어 올리자 음식 대신 예상 밖의 물건이 보인다. 익숙한 식사 동작을 공개 장면의 연출로 바꾼다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005159/index.html"},{"id":"MEJE-KW-005160","row_version":2,"title":"서로 다른 시각을 가리키는 시계들","original":"Clock Discrepancy","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"두 시계나 기록의 시간이 맞지 않아 사건 발생 시각에 의문이 생긴다. 작은 차이가 알리바이와 사건 순서를 다시 보게 한다. 시계의 차이가 우연인지 누군가의 조작인지에 따라 사건의 뜻이 달라진다: 시계 시간을 일부러 바꾸기.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005160/index.html"},{"id":"MEJE-KW-005161","row_version":2,"title":"초 단위까지 따지는 계획가","original":"Clock King","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 주변의 일정과 이동 시간을 세밀하게 계산해 계획을 세운다. 정밀함이 능력이 되지만 예상 밖의 변수 앞에서는 약점도 된다. 치밀한 시간 계산이 가까운 사람의 행동을 맞히는 장면으로 나타나기도 한다: 결과를 초 단위로 예견하는 친구.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005161/index.html"},{"id":"MEJE-KW-005162","row_version":1,"title":"초능력을 지닌 시계","original":"Clock of Power","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"시계나 모래시계가 시간을 다루거나 다른 특별한 힘을 내는 물건으로 등장한다. 시간을 재는 도구의 기능이 세계의 규칙을 움직이는 힘으로 확장된다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-005162/index.html"},{"id":"MEJE-KW-005163","row_version":3,"title":"태엽과 톱니바퀴의 대체 역사","original":"Clock Punk","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"정교한 태엽 장치가 사회의 기술과 일상 풍경을 지배하는 상상적 시대 양식이다. 기계의 노출된 움직임이 세계의 미감을 만든다. 태엽 기술이 세계의 일상이라면 살아 움직이는 기계 생물도 자연스럽게 들어온다: 태엽으로 움직이는 생물. 톱니바퀴의 미감이 인물이 직접 통과해야 할 공간으로 구현되기도 한다: 거대한 톱니바퀴 사이를 통과하기.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-005163/index.html"},{"id":"MEJE-KW-005164","row_version":2,"title":"시간을 어지럽히는 자를 쫓는 존재","original":"Clock Roaches","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"시간의 흐름이 바뀌면 이를 알아차리고 개입하는 기이한 존재가 나타난다. 세계가 스스로 인과관계를 지키려 한다는 인상을 준다. 시간의 변경을 감시하는 존재가 있어도 원래대로 완전히 돌아가지 못한 세계는 남을 수 있다: 완벽하지 않아도 받아들인 시간선.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-005164/index.html"},{"id":"MEJE-KW-005165","row_version":2,"title":"시계로 나타내는 통제 욕망","original":"Clocks of Control","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"질서와 통제에 집착하는 인물이나 조직을 시계와 맞물린 톱니바퀴의 이미지로 표현한다. 규칙적으로 움직이는 장치가 사람을 부품처럼 다루는 사고를 비춘다. 시계가 상징하는 질서 집착은 인물의 초 단위 계획으로도 구체화된다: 초 단위까지 따지는 계획가.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-005165/index.html"},{"id":"MEJE-KW-005166","row_version":1,"title":"열세 번 울리는 시계","original":"Clock Strikes Thirteen","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"시계가 익숙한 시간을 벗어나 열세 번 종을 울려 이상한 일이 시작됐음을 알린다. 어긋난 숫자가 일상의 규칙이 무너지는 신호가 된다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005166/index.html"},{"id":"MEJE-KW-005167","row_version":1,"title":"시계 시간을 일부러 바꾸기","original":"Clock Tampering","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 시계의 표시를 바꿔 다른 사람들이 사건의 시각을 잘못 믿게 만든다. 객관적인 듯 보이는 도구에 대한 신뢰가 반전의 바탕이 된다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005167/index.html"},{"id":"MEJE-KW-005168","row_version":2,"title":"도시 위에 선 시계탑","original":"Clock Tower","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"멀리서도 보이는 시계탑이 장소의 표식이자 인물들이 모이는 무대가 된다. 높은 위치와 공공의 시간을 함께 보여 준다. 시계탑의 안쪽으로 들어가면 톱니바퀴가 이동 경로가 되는 장면으로 이어진다: 거대한 톱니바퀴 사이를 통과하기.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005168/index.html"},{"id":"MEJE-KW-005169","row_version":1,"title":"태엽으로 움직이는 생물","original":"Clockwork Creature","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"태엽과 톱니바퀴로 만들어진 존재가 생물처럼 걷고 반응한다. 기계의 정밀함과 살아 있는 듯한 행동이 한 몸에 겹친다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-005169/index.html"},{"id":"MEJE-KW-005170","row_version":1,"title":"결과를 초 단위로 예견하는 친구","original":"Clockwork Prediction","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"한 인물이 가까운 사람의 행동을 너무 잘 알아 곧 벌어질 소동을 정확한 순간에 맞춰 예고한다. 뒤따르는 사건이 오래 쌓인 친숙함을 확인한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-005170/index.html"},{"id":"MEJE-KW-005171","row_version":1,"title":"거대한 톱니바퀴 사이를 통과하기","original":"Clockworks Area","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물이 커다란 시계 장치나 공장의 회전 구조물 사이로 이동한다. 배경 기계가 단순한 장식에서 움직이는 지형으로 바뀐다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005171/index.html"},{"id":"MEJE-KW-005172","row_version":2,"title":"복제인간의 정체성 불안","original":"Clone Angst","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"복제된 인물이 자신을 원본의 대체품이나 소모품으로 취급하는 시선에 괴로워한다. 같은 외모와 별개의 삶 사이에서 자기 정체성을 찾는다. 복제체의 괴로움은 그를 원본과 별개인 사람으로 대할 때 다른 방향으로 풀린다: 복제인간도 한 사람으로 대하기.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-005172/index.html"},{"id":"MEJE-KW-005173","row_version":2,"title":"복제인간으로 만든 군대","original":"Clone Army","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"한 사람이나 소수의 유전적 원형에서 많은 병사를 만들어 군대를 꾸린다. 대량 생산의 효율 뒤에 개별 병사의 권리와 차이를 묻는 문제가 생긴다. 대량 생산된 병사에게도 각자의 삶이 있다는 관점은 군대의 규칙과 충돌할 수 있다: 복제인간도 한 사람으로 대하기.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-005173/index.html"},{"id":"MEJE-KW-005174","row_version":2,"title":"타인을 자기 복제체로 바꾸기","original":"Clone by Conversion","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"기존 인물이 새로운 개체로 복사되는 대신 다른 사람이 한 존재의 복제체로 변한다. 복제가 곧 타인의 정체성을 지우는 침범이 된다. 기존 인물을 복제체로 바꾸는 설정이라면 새 정체성을 어떻게 받아들이는지도 문제가 된다: 복제인간의 정체성 불안.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005174/index.html"},{"id":"MEJE-KW-005175","row_version":2,"title":"복제를 거듭할수록 약해지기","original":"Clone Degeneration","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"복제물이나 복제 기술의 결과가 반복될수록 불안정하거나 약해진다는 규칙이다. 똑같이 늘릴 수 있다는 기대에 한계를 부여한다. 복제의 한계를 개별 복제체의 약화가 아니라 능력의 분배로 표현하는 방식도 있다: 분열한 복제체에게 능력이 나뉘기.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005175/index.html"},{"id":"MEJE-KW-005176","row_version":1,"title":"성스러운 인물을 복제하려는 시도","original":"Clone Jesus","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"성스러운 인물의 몸에서 남은 자료를 이용해 그 인물을 다시 만들려는 시도가 벌어진다. 과학적 재현과 신앙의 고유성이 충돌한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005176/index.html"},{"id":"MEJE-KW-005177","row_version":1,"title":"독점 보드게임을 닮은 가상 게임","original":"Cloneopoly","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"작품 안에 땅을 사고 거래하는 유명 보드게임을 닮은 별도 게임이 등장한다. 익숙한 규칙을 빌려 작중 문화나 풍자를 빠르게 전달한다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005177/index.html"},{"id":"MEJE-KW-005178","row_version":2,"title":"복제인간도 한 사람으로 대하기","original":"Clones Are People, Too","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"이야기가 복제된 존재에게 원본과 별개의 의지와 삶이 있음을 인정한다. 만들어진 방식보다 경험과 선택을 사람을 대하는 기준으로 삼는다. 복제체를 독립된 사람으로 본다면 위험을 대신 떠맡기는 계획에도 윤리적 문제가 생긴다: 복제체를 이용한 생존 계획.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-005178/index.html"},{"id":"MEJE-KW-005179","row_version":1,"title":"복제 기술로 몸의 일부 되살리기","original":"Cloning Body Parts","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 잃은 신체 부위를 자신의 세포에서 다시 자라게 하는 기술을 사용한다. 몸의 회복 가능성이 치료와 정체성의 경계를 넓힌다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-005179/index.html"},{"id":"MEJE-KW-005180","row_version":1,"title":"복제체를 이용한 생존 계획","original":"Cloning Gambit","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 복제한 몸을 자신의 죽음을 대비한 수단이나 위험한 임무의 대리인으로 삼는다. 원본과 복제체 중 누구의 삶을 우선하는지가 갈등을 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005180/index.html"},{"id":"MEJE-KW-005181","row_version":1,"title":"분열한 복제체에게 능력이 나뉘기","original":"Cloning Splits Attributes","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인물이 여러 몸으로 나뉘면 원래 갖고 있던 재능이나 성격도 각자에게 갈라진다. 수가 늘어나는 이익과 개별 능력의 손실이 맞물린다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-005181/index.html"},{"id":"MEJE-KW-005182","row_version":1,"title":"아슬아슬하게 머리카락만 스치는 공격","original":"Close-Call Haircut","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"공격이 몸을 비껴가며 머리카락 몇 가닥만 잘린다. 작은 흔적이 방금 지나간 위험을 시각적으로 확인시킨다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005182/index.html"},{"id":"MEJE-KW-005183","row_version":1,"title":"위험에 바짝 다가가면 얻는 보상","original":"Close-Contact Danger Benefit","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 공격에 맞지 않을 만큼만 가까이 다가가면 점수나 자원이 쌓인다. 안전한 회피와 위험을 감수한 접근 사이에 선택을 만든다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-005183/index.html"},{"id":"MEJE-KW-005184","row_version":1,"title":"외부와 단절된 사건 현장","original":"Closed Circle","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물들이 밖과 연락하거나 빠져나갈 수 없는 장소에 갇혀 사건을 겪는다. 용의자와 해결 단서의 범위가 좁아지며 서로를 의심하게 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005184/index.html"},{"id":"MEJE-KW-005185","row_version":1,"title":"닫힌 문을 사이에 둔 대화","original":"Closed Door Rapport","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"한 사람은 문을 닫아 거리를 두고 다른 사람은 그 너머에서 말을 건다. 물리적 경계가 관계의 긴장과 화해의 어려움을 눈에 보이게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005185/index.html"},{"id":"MEJE-KW-005186","row_version":1,"title":"완벽하지 않아도 받아들인 시간선","original":"Close-Enough Timeline","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"과거를 고치려던 인물이 원래 역사와 조금 다른 현재에 도착하지만 그 차이를 감수한다. 되돌리기의 성공보다 새 현실을 받아들일지가 결말이 된다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-005186/index.html"},{"id":"MEJE-KW-005187","row_version":1,"title":"서로를 돌보는 동네 공동체","original":"Close-Knit Community","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"같은 지역에 사는 사람들이 일상적으로 서로를 알고 도와준다. 공동 목표가 없어도 반복되는 돌봄이 공간의 성격을 만든다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-005187/index.html"},{"id":"MEJE-KW-005188","row_version":2,"title":"작품 끝에 나타나는 제목","original":"Close on Title","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"보통 초반에 나오는 제목 자막을 결말 뒤로 미룬다. 이야기를 겪고 난 뒤에야 제목의 뜻을 다시 읽게 한다. 끝에 나타나는 제목은 제작진 이름이 흐르는 형식과 맞물려 마지막 인상을 만들 수 있다: 작품 끝에 흐르는 제작진 명단.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005188/index.html"},{"id":"MEJE-KW-005189","row_version":1,"title":"근거리 싸움에 특화된 전투원","original":"Close-Range Combatant","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"가까이 붙어 싸울 때 강하지만 먼 거리에서 쓸 수 있는 수단은 제한적인 인물이다. 상대와 거리를 좁히는 과정이 전투의 핵심이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005189/index.html"},{"id":"MEJE-KW-005190","row_version":1,"title":"거울 속 추격자가 생각보다 가까움","original":"Closer than They Appear","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"거울의 거리감과 경고 문구를 이용해 뒤따르는 적이 이미 가까이 와 있음을 드러낸다. 익숙한 차량 표기가 장면의 긴장이나 농담으로 바뀐다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005190/index.html"},{"id":"MEJE-KW-005191","row_version":1,"title":"소수자를 자연과 더 가깝다고 보는 시선","original":"Closer to Earth","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"소수민족 인물을 타고나기를 자연의 신호를 읽는 사람처럼 묘사한다. 개인의 지식과 경험을 혈통의 신비한 성질로 바꾸는 고정관념이 될 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005191/index.html"},{"id":"MEJE-KW-005192","row_version":1,"title":"가장 비슷한 전문가에게 맡기기","original":"Closest Thing We Got","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"필요한 전문가가 없는 상황에서 관련 경험이 조금이라도 있는 사람에게 도움을 청한다. 부족함을 알면서도 지금 가진 자원에 기대야 하는 긴박함이 드러난다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005192/index.html"},{"id":"MEJE-KW-005193","row_version":2,"title":"성적 지향을 숨기는 인물","original":"Closet Gay","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 차별이나 관계의 단절을 우려해 자신의 성적 지향을 드러내지 않는다. 숨겨야 한다는 압박과 안전한 관계를 찾고 싶은 마음이 함께 작동한다. 자신의 성적 지향을 드러내지 못하던 인물이 한 사람과의 만남으로 스스로를 새롭게 이해하기도 한다: 자기 성적 지향을 깨닫게 한 사람.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005193/index.html"},{"id":"MEJE-KW-005194","row_version":1,"title":"취향을 숨기는 팬","original":"Closet Geek","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 판타지나 게임 같은 취미를 즐기면서도 주변의 시선을 의식해 감춘다. 남에게 보이는 모습과 혼자 있을 때의 열정 사이에 간극이 생긴다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-005194/index.html"},{"id":"MEJE-KW-005195","row_version":1,"title":"자기 성적 지향을 깨닫게 한 사람","original":"Closet Key","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"한 인물과의 만남이 다른 인물이 자신의 성적 지향을 새롭게 이해하는 계기가 된다. 상대를 통해 알게 된 감정이 정체성의 언어를 바꾼다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-005195/index.html"},{"id":"MEJE-KW-005196","row_version":1,"title":"사건이 자신의 상처를 건드리기","original":"Close to Home","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"맡은 사건이 인물의 과거 경험과 닮아 감정과 판단을 흔든다. 공감이 힘이 되기도 하지만 문제를 바라보는 거리를 좁힌다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-005196/index.html"},{"id":"MEJE-KW-005197","row_version":1,"title":"아이를 좁은 곳에 가두는 벌","original":"Closet Punishment","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"어른이 아이를 좁은 공간에 가두는 벌을 내려 두려움과 권력 차이를 드러낸다. 훈육이라는 이름으로 행해진 학대의 한 모습이다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005197/index.html"},{"id":"MEJE-KW-005198","row_version":1,"title":"숨겨 둔 사람을 계속 옮기는 소동","original":"Closet Shuffle","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"들키면 곤란한 사람을 숨기려다 다른 방문자가 나타날 때마다 장소를 옮긴다. 숨길 사람이 늘수록 공간과 거짓말의 관리가 어려워진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-005198/index.html"},{"id":"MEJE-KW-005199","row_version":1,"title":"옷장 속에 사는 동거인","original":"Closet Sublet","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"한 인물이 방 대신 다른 사람의 옷장이나 비슷한 좁은 공간을 생활 터전으로 삼는다. 비정상적으로 작은 주거 공간이 동거의 소동을 만든다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-005199/index.html"},{"id":"MEJE-KW-005200","row_version":1,"title":"머리만 보이다가 배경을 드러내는 화면","original":"Closeup on Head","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 머리만 크게 보여 준 뒤 화면을 넓혀 뜻밖의 주변 상황을 공개한다. 늦게 드러난 공간 정보가 앞선 표정이나 대사를 다시 해석하게 한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-005200/index.html"},{"id":"MEJE-KW-005201","row_version":1,"title":"작품 끝에 흐르는 제작진 명단","original":"Closing Credits","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"영화나 프로그램이 끝난 뒤 참여자의 이름과 역할을 차례로 보여 준다. 이야기의 마무리와 제작에 참여한 사람들의 기록을 잇는 형식이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-005201/index.html"}]}.cards;